import {AnatomyAnimator} from './animator.js';
import {AudioEngine} from './audioEngine.js';
import {loadState,saveState,recordArticulation,recordVoice,dailyGoalComplete,syncDay,resetDailyFlagsIfNewDay,reconcileStreak,getMonthCalendar,localDate,tierStatus} from './gamification.js';
import {flashSuccess,showNudge} from './ui.js';
const state=loadState();resetDailyFlagsIfNewDay(state);reconcileStreak(state);let route=['home','practice','progress','settings'].includes(location.hash.slice(1))?location.hash.slice(1):'home',mode='articulation',tokens=[],activeIndex=0,animator=null,audio=null,playRaf=0,voiceRaf=0,isPlaying=false,voiceRunning=false,activeExercise=null,exerciseStarted=0,exerciseMetrics={pitches:[],pitchBreaks:0,volumes:[],lastPitch:0,lastAt:0},articulationWaveHistory=[],exerciseWaveHistory=[];
const content=document.querySelector('#app-content');
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const todayFmt=new Intl.DateTimeFormat('en-IN',{weekday:'long',month:'long',day:'numeric'}).format(new Date());
let lastDisplayedStreak=state.streakData.current;let sessionStarted=false,reminderShown=false,calendarMonthOffset=0;
function navSync(){document.querySelectorAll('[data-route]').forEach(b=>b.classList.toggle('active',b.dataset.route===route));document.querySelector('#crumb-current').textContent=route.toUpperCase();const counter=document.querySelector('#streak-count'),next=String(state.streakData.current);if(counter&&counter.textContent!==next){counter.textContent=next;counter.classList.remove('slot-roll');void counter.offsetWidth;counter.classList.add('slot-roll');setTimeout(()=>counter.classList.remove('slot-roll'),420);lastDisplayedStreak=state.streakData.current;}document.querySelector('#side-level').textContent=state.progressData.level;}
function toast(message,type=''){const el=document.createElement('div');el.className=`toast ${type}`;el.textContent=message;document.querySelector('#toast-region').append(el);setTimeout(()=>el.remove(),3200);}
function cleanup(){animator?.destroy();animator=null;audio?.stop();audio=null;cancelAnimationFrame(playRaf);cancelAnimationFrame(voiceRaf);isPlaying=false;voiceRunning=false;}
function go(next){if(route===next)return;if(next==='practice')sessionStarted=true;cleanup();route=next;history.pushState({route:next},'',`#${next}`);navSync();render();window.scrollTo({top:0,behavior:state.settings.reducedMotion?'auto':'smooth'});}
function render(){content.innerHTML=route==='home'?homeView():route==='practice'?practiceView():route==='progress'?progressView():settingsView();if(route==='practice')bindPractice();if(route==='settings')bindSettings();}
function dailyPlanView(){const art=state.progressData.articulationToday,voice=state.progressData.voiceToday,done=Number(art)+Number(voice);return `<section class="daily-route"><div class="daily-route-head"><div><div class="eyebrow">YOUR TWO-PART PRACTICE</div><h3>A small, complete session</h3><p>One word + one voice set. Repeat only as it feels helpful.</p></div><div class="daily-route-progress" style="--pct:${done*50}%"><strong>${done}<i>/ 2</i></strong><small>steps done</small></div></div><div class="daily-route-steps"><button class="route-step ${art?'complete':''}" data-route="practice" data-mode="articulation"><span class="step-index">${art?'✓':'01'}</span><span class="step-copy"><b>Explore a Hindi word</b><small>Sound placement · self-report</small></span><span class="step-state">${art?'Complete':'Begin'} →</span></button><button class="route-step ${voice?'complete':''}" data-route="practice" data-mode="voice"><span class="step-index">${voice?'✓':'02'}</span><span class="step-copy"><b>Choose a voice exercise</b><small>${(state.assessmentData.concerns||[]).includes('denasalization')?'Velum awareness · oral airflow':(state.assessmentData.concerns||[]).includes('stability')?'Easy glide · vocal stability':'Breath · resonance · steadiness'}</small></span><span class="step-state">${voice?'Complete':'Begin'} →</span></button></div><div class="daily-route-foot"><span>✦ &nbsp;Finish both to complete today’s goal</span><span>About 5–8 minutes</span></div></section>`;}
function homeView(){const xp=state.progressData.xp,level=state.progressData.level,within=xp%100,done=dailyGoalComplete(state),focus=state.assessmentData.concerns||[],voiceFirst=focus.some(x=>['denasalization','stability','resonance'].includes(x));const week=[];for(let i=6;i>=0;i--){const d=new Date();d.setDate(d.getDate()-i);const status=state.streakData.calendar[localDate(d)];week.push(`<div class="day-cell"><small>${new Intl.DateTimeFormat('en-IN',{weekday:'short'}).format(d)}</small><div class="day-dot ${status==='complete'?'done':status==='partial'?'partial':status==='rest'?'rest':''} ${i===0?'today':''}">${status==='complete'?'✓':status==='partial'?'•':status==='rest'?'↺':i===0?'•':''}</div></div>`);}
return `<div class="welcome-row"><div><div class="eyebrow">${todayFmt}</div><h1>Find your voice, <span style="color:#54ae9f">one day at a time.</span></h1><p>A little practice today can make a meaningful difference.</p></div><div class="date-note">Your personal practice space</div></div><section class="hero"><div class="hero-copy"><div class="eyebrow">TODAY'S GENTLE PLAN</div><h2>${done?'Beautiful work today.':'Let’s begin with a small win.'}</h2><p>${done?'Your articulation and voice practice are both complete. Notice what feels easier.':voiceFirst?'Your plan starts with a gentle voice exercise, based on the goals you chose.':'Start with one Hindi word, then choose a voice exercise that feels comfortable for you.'}</p><button class="primary-btn" data-action="start-practice">${done?'Continue exploring':'Start today’s practice'} <span>→</span></button></div><div class="hero-visual" aria-hidden="true"><svg class="hero-illustration" viewBox="0 0 420 280" role="presentation"><defs><radialGradient id="voiceGlow"><stop stop-color="#a0e9d8" stop-opacity=".6"/><stop offset="1" stop-color="#a0e9d8" stop-opacity="0"/></radialGradient><linearGradient id="waveInk" x1="0" x2="1"><stop stop-color="#a2ecd9"/><stop offset="1" stop-color="#f2c47d"/></linearGradient></defs><circle cx="231" cy="137" r="128" fill="url(#voiceGlow)"/><circle class="orbit orbit-a" cx="231" cy="137" r="104"/><circle class="orbit orbit-b" cx="231" cy="137" r="81"/><circle cx="231" cy="137" r="61" fill="#ffffff12" stroke="#ffffff47"/><path class="voice-wave" d="M48 141 C77 141 77 92 106 92 S135 184 164 184 193 103 222 103 251 165 280 165 309 118 338 118 367 141 402 141" fill="none" stroke="url(#waveInk)" stroke-width="3" stroke-linecap="round"/><text x="231" y="155" text-anchor="middle" class="hero-glyph">आ</text><circle class="sound-dot dot-a" cx="100" cy="71" r="4"/><circle class="sound-dot dot-b" cx="342" cy="199" r="5"/><path d="M286 53l4 11 11 4-11 4-4 11-4-11-11-4 11-4z" fill="#f0c982" opacity=".8"/></svg><div class="hero-caption"><span>sound · breath · confidence</span><i></i><b>आ</b></div></div></section>${dailyPlanView()}<div class="section-heading"><h3>Your practice areas</h3><button data-action="go-practice">Explore all →</button></div><div class="module-grid"><div class="module-card" data-route="practice" data-mode="articulation"><div class="module-head"><span class="module-icon mint">अ</span></div><div class="ring" style="--pct:${state.progressData.articulationToday?100:0}"><span>${state.progressData.articulationToday?'✓':'0%'}</span></div><h4>Articulation</h4><p>Explore Hindi sounds and mouth shapes</p><div class="card-foot"><span>${state.progressData.words} words practiced</span><strong>${state.progressData.articulationToday?'Done today':'Start a word'} →</strong></div></div><div class="module-card" data-route="practice" data-mode="voice"><div class="module-head"><span class="module-icon peach">♫</span></div><div class="ring" style="--pct:${state.progressData.voiceToday?100:0}"><span>${state.progressData.voiceToday?'✓':'0%'}</span></div><h4>Voice & breath</h4><p>Build calm, steady vocal habits</p><div class="card-foot"><span>${state.progressData.exercises} sessions completed</span><strong>${state.progressData.voiceToday?'Done today':'Choose an exercise'} →</strong></div></div><div class="module-card" data-route="progress"><div class="module-head"><span class="module-icon violet">✧</span></div><div class="ring" style="--pct:${Math.min(100,within)}"><span>${within}%</span></div><h4>Progress</h4><p>Celebrate the practice you’ve built</p><div class="card-foot"><span>Best streak: ${state.streakData.best} days</span><strong>View progress →</strong></div></div></div><div class="dashboard-bottom"><section class="panel"><div class="panel-title"><h3>Your week</h3><span>Consistency over perfection</span></div><div class="week-row">${week.join('')}</div><div class="daily-mini"><span>Daily goal <strong>${state.progressData.articulationToday?'✓':'○'} Articulation</strong> · <strong>${state.progressData.voiceToday?'✓':'○'} Voice</strong></span><span>${state.streakData.freezeTokens} rest token${state.streakData.freezeTokens===1?'':'s'}</span></div></section><section class="panel"><div class="panel-title"><h3>Your growth</h3><span>Level ${level}</span></div><div class="xp-row"><div class="level-badge">${level}</div><div class="xp-info"><div><strong>Level ${level} learner</strong><span>${within} / 100 XP</span></div><div class="progress-track"><div class="progress-fill" style="--width:${within}%"></div></div></div></div><div class="daily-mini"><span>Total experience</span><strong>${xp} XP</strong></div></section></div>`;}
function soundLibraryMarkup(){const vargas=[['क-वर्ग','क','ख','ग','घ','ङ'],['च-वर्ग','च','छ','ज','झ','ञ'],['ट-वर्ग','ट','ठ','ड','ढ','ण'],['त-वर्ग','त','थ','द','ध','न'],['प-वर्ग','प','फ','ब','भ','म']],others=Object.values(phonemeData).filter(p=>p.manner!=='vowel'&&!vargas.some(v=>v.slice(1).includes(p.char))).map(p=>p.char),chip=(word)=>`<button class="sample-chip library-chip" data-word="${word}">${word}</button>`;return `<details class="sound-library"><summary>Open Hindi sound library <span>vowels · varga · matra · conjuncts</span></summary><div class="sound-library-body"><strong>Swar · स्वतंत्र स्वर</strong><div class="sample-words">${vowelData.map(v=>chip(v.char)).join('')}</div>${vargas.map(([name,...items])=>`<strong>${name}</strong><div class="sample-words">${items.map(chip).join('')}</div>`).join('')}<strong>Other consonants</strong><div class="sample-words">${[...new Set(others)].map(chip).join('')}</div><strong>Matras · consonant + sign</strong><div class="sample-words">${Object.keys(matraMap).map(m=>chip(`क${m}`)).join('')}</div><strong>Conjuncts & modifiers</strong><div class="sample-words">${Object.keys(conjuncts).map(chip).join('')}${['मं','चाँद','हः'].map(chip).join('')}</div></div></details>`;}
function practiceView(){return `<div class="practice-heading"><div class="eyebrow">YOUR PRACTICE SPACE</div><h1>Practice with purpose.</h1><p style="color:var(--muted);font-size:12px;margin:0">Go at your own pace. Your voice is not being judged.</p></div><div class="practice-tabs"><button class="practice-tab ${mode==='articulation'?'active':''}" data-mode="articulation">अ &nbsp; Articulation</button><button class="practice-tab ${mode==='voice'?'active':''}" data-mode="voice">♫ &nbsp; Voice & breath</button></div><section class="articulation-view ${mode==='voice'?'hidden':''}"><div class="practice-layout"><div class="practice-column"><div class="input-card"><div class="card-label">TYPE A WORD TO EXPLORE</div><input class="word-input" id="word-input" value="कमल" aria-label="Hindi or Hinglish word" placeholder="कमल or kamal" autocomplete="off"><div class="helper">Try Devanagari or Hinglish transliteration. This is a learning aid, not a clinical assessment.</div>${state.assessmentData.focusVowels?.length?`<div class="focus-note">From your self-check, you may want to revisit: <strong>${state.assessmentData.focusVowels.join(' · ')}</strong></div>`:''}<div class="sample-words">${['कमल','पानी','नमस्ते','क्षमा','श्रद्धा'].map(w=>`<button class="sample-chip" data-word="${w}">${w}</button>`).join('')}</div>${soundLibraryMarkup()}</div><div class="input-card" style="padding:14px 17px"><div class="card-label">SOUND-BY-SOUND MAP <span id="token-count"></span></div><div class="phoneme-strip" id="phoneme-strip"></div></div><div class="lesson-card" id="lesson-card"></div><div class="action-row"><button class="primary-btn" data-action="mark-articulation">✓ &nbsp; I practiced this word</button></div><div class="self-report"><button class="good" data-action="self-correct">✓ &nbsp; Felt comfortable</button><button class="needs" data-action="self-work">↻ &nbsp; Needs more practice</button></div></div><div class="practice-column"><div class="diagram-card"><div class="diagram-title"><h3>Inside the sound</h3><span>Illustrative mouth map · not to scale</span></div><canvas id="anatomy-canvas" class="anatomy-canvas" aria-label="Animated sagittal mouth diagram"></canvas><div class="diagram-legend"><span class="legend-item"><i class="legend-dot"></i>Active articulator</span><span class="legend-item"><i class="legend-dot blue"></i>Airflow</span><span class="legend-item"><i class="legend-dot green"></i>Velum</span></div><div class="diagram-controls"><label class="toggle-label"><input class="switch" id="mirror-toggle" type="checkbox" ${state.settings.mirror?'checked':''}> Mirror view</label><label class="toggle-label"><input class="switch" id="loop-toggle" type="checkbox"> Loop</label><select class="speed-select" id="loop-mode" aria-label="Loop mode"><option value="word">Word</option><option value="sound">Selected sound</option></select><button class="outline-btn" id="mic-button" style="padding:7px 9px;font-size:9px">◉ Try mic</button></div><div class="playback"><button class="play-button" id="play-button">▶</button><input id="timeline" class="timeline" type="range" min="0" max="100" value="0" aria-label="Word playback position"><select class="speed-select" id="speed-select"><option value="slow">Slow</option><option value="natural">Natural</option></select></div><div id="audio-feedback" style="display:none;margin-top:12px"><div style="display:flex;justify-content:space-between;font-size:9px;color:#8492a2"><span>Live audio · experimental tongue estimate</span><span id="pitch-readout">Pitch —</span></div><div class="meter"><span id="audio-meter"></span></div><div id="nasality-hint" class="helper" style="display:none;margin-top:5px;color:#cc7568">Estimated nasal energy is elevated. For an oral sound, try a gentle velum lift. This estimate may be inaccurate.</div><div id="wave-bars" style="height:32px;display:flex;align-items:end;gap:3px;margin-top:8px"></div></div></div></div></section><section class="voice-view ${mode==='voice'?'active':''}"><div class="eyebrow" style="margin-bottom:11px">CHOOSE WHAT FEELS RIGHT TODAY</div><div class="exercise-grid">${exerciseCards()}</div><div class="active-exercise" id="active-exercise"></div></section>`;}
function exerciseCards(){const ex=[
 ['breathing','◌','Diaphragmatic breathing','Six gentle 4–4–8 cycles with a visual breath guide.','~2 min','Breath'],
 ['yawn','◡','Velum awareness · yawn–sigh','Five easy yawn-to-sigh repetitions. Never force a yawn.','~1 min','Oral airflow'],
 ['nose-pinch','⇄','Nose-pinch contrast','Self-check oral vowels and nasal sounds; the app does not diagnose.','~2 min','Awareness'],
 ['vowels','आ','Sustained oral vowels','Move through ten vowels with relaxed airflow.','~2 min','De-nasalization'],
 ['chains','क','Progressive syllable chains','Practice oral syllables, then notice velum changes in words.','~1 min','Coarticulation'],
 ['liptrill','♧','Lip trills · easy glide','Gentle motorboat lips with a comfortable pitch contour.','~1 min','Stability'],
 ['straw','◉','Straw-style phonation','Narrow-lip humming, glides, then an easy scale.','~1 min','SOVT'],
 ['siren','〰','Gentle voice siren','Five slow upward and downward “woo” glides.','~2 min','Stability'],
 ['messa','◇','Messa di voce','Three soft–louder–soft swells while keeping pitch easy.','~1 min','Control'],
 ['humming','♫','Chest resonance hum','Comfortable hum and a descending five-note pattern.','~1 min','Resonance'],
 ['reading','文','Paced Hindi reading','Read a calm passage with breath cues and word pacing.','~1 min','Fluency'],
 ['relax','☼','Pant to yawn','Four gentle pant-to-yawn releases; stop if uncomfortable.','~1 min','Relaxation']
 ];const concern=(state.assessmentData.concerns||[]).find(c=>c!=='articulation'),priority={denasalization:['yawn','nose-pinch','vowels','chains'],stability:['liptrill','straw','siren','messa'],resonance:['breathing','humming','reading','relax']}[concern]||[];ex.sort((a,b)=>{const ai=priority.indexOf(a[0]),bi=priority.indexOf(b[0]);return (ai<0?99:ai)-(bi<0?99:bi);});return ex.map(([id,icon,title,desc,dur,tag],i)=>`<article class="exercise-card" data-exercise="${id}" style="animation-delay:${i*25}ms"><div class="module-icon ${i%3===0?'mint':i%3===1?'peach':'violet'}">${icon}</div><h4>${title}</h4><p>${desc}</p><div class="exercise-meta"><b>${dur}</b><span>${tag} &nbsp; →</span></div></article>`).join('');}
function progressView(){
 const calendar=getMonthCalendar(state,calendarMonthOffset),tiers=tierStatus(state),xp=state.progressData.xp;
 const activityDays=new Set(state.practiceHistory.filter(item=>['articulation','voice'].includes(item.type)).map(item=>item.date)).size;
 const cells=calendar.cells.map(cell=>cell.empty?'<span class="calendar-cell empty" aria-hidden="true"></span>':`<div class="calendar-cell ${cell.status} ${cell.today?'today':''}" role="gridcell" aria-label="${cell.date}: ${cell.status}" title="${cell.date} · ${cell.status}"><span>${cell.day}</span>${cell.status==='complete'?'<i>✓</i>':cell.status==='partial'?'<i>•</i>':cell.status==='rest'?'<i>↺</i>':''}</div>`).join('');
 const weekdays=calendar.weekdays.map(day=>`<span>${day}</span>`).join('');
 return `<div class="practice-heading progress-heading"><div class="eyebrow">YOUR PRACTICE, OVER TIME</div><h1>Consistency you can see.</h1><p>Practice days, calendar dates and your daily goal—clearly tracked in your local time.</p></div>
 <div class="stats-grid progress-stats"><div class="stat-card"><small>Goal streak</small><strong>${state.streakData.current} <em>days</em></strong><span>Best streak: ${state.streakData.best} days</span></div><div class="stat-card"><small>Days you practiced</small><strong>${activityDays}</strong><span>Days with at least one saved activity</span></div><div class="stat-card"><small>Experience earned</small><strong>${xp} <em>XP</em></strong><span>Level ${state.progressData.level}</span></div></div>
 <div class="progress-panels"><section class="panel calendar-panel"><div class="panel-title calendar-title"><div><div class="eyebrow">DAY-BY-DAY VIEW</div><h3>Practice calendar</h3><span>${calendar.completeCount} complete · ${calendar.partialCount} partial this month</span></div><div class="calendar-navigation"><button class="calendar-nav" data-action="calendar-prev" aria-label="Previous month">‹</button><strong>${calendar.monthLabel}</strong><button class="calendar-nav" data-action="calendar-next" aria-label="Next month" ${calendar.monthOffset>=0?'disabled':''}>›</button></div></div><div class="calendar-weekdays" aria-hidden="true">${weekdays}</div><div class="calendar-grid calendar-month" role="grid" aria-label="${calendar.monthLabel} practice calendar">${cells}</div><div class="calendar-legend"><span><i class="complete"></i>Daily goal</span><span><i class="partial"></i>Practice logged</span><span><i class="rest"></i>Rest token</span><span><i class="missed"></i>Missed</span></div><p class="calendar-footnote">A complete streak day means both parts of your daily goal are done. Partial practice is still recorded and counts as a practice day.</p></section><section class="panel learning-panel"><div class="panel-title"><div><div class="eyebrow">YOUR LEARNING PATH</div><h3>Sound journeys</h3></div><span>At your pace</span></div>${tiers.map((t,i)=>`<div class="tier-row ${t.done?'tier-done':''} ${t.unlocked?'':'tier-locked'}"><div class="tier-mark">${t.done?'✓':t.unlocked?String(i+1).padStart(2,'0'):'· · ·'}</div><div><strong>${t.name} <span>${t.hi}</span></strong><small>${t.description}</small><small class="tier-progress">${t.progress}</small></div></div>`).join('')}</section></div>
 <section class="panel summary-panel"><div class="panel-title"><div><div class="eyebrow">YOUR TOTALS</div><h3>All-time practice</h3></div><span>Saved on this device</span></div><div class="summary-grid"><div><small>Hindi words</small><strong>${state.progressData.words}</strong></div><div><small>Voice sessions</small><strong>${state.progressData.exercises}</strong></div><div><small>Best day streak</small><strong>${state.streakData.best}</strong></div><div><small>Rest tokens</small><strong>${state.streakData.freezeTokens} <em>available</em></strong></div></div></section>`;
}
function settingsView(){const s=state.settings;return `<div class="practice-heading"><div class="eyebrow">MAKE IT FEEL LIKE YOUR SPACE</div><h1>Settings & accessibility.</h1><p style="color:var(--muted);font-size:12px;margin:0">Adjust the experience to suit your eyes, pace and preferences.</p></div><div class="setting-group"><div class="setting-row"><div><strong>Appearance</strong><small>Choose a comfortable color theme</small></div><select id="theme-setting"><option value="light" ${s.theme==='light'?'selected':''}>Light</option><option value="dark" ${s.theme==='dark'?'selected':''}>Dark</option></select></div><div class="setting-row"><div><strong>Animation speed</strong><small>0.5× study pace to 2× quick review</small></div><input id="speed-setting" type="range" min="0.5" max="2" step="0.1" value="${s.animationSpeed}"><strong id="speed-value">${Number(s.animationSpeed).toFixed(1)}×</strong></div><div class="setting-row"><div><strong>Hindi text size</strong><small>Increase Devanagari text across practice</small></div><input id="font-setting" type="range" min="0.9" max="1.3" step="0.1" value="${s.fontSize}"></div><div class="setting-row"><div><strong>Instructions</strong><small>Display coaching text in</small></div><select id="language-setting"><option value="en" ${s.language==='en'?'selected':''}>English</option><option value="hi" ${s.language==='hi'?'selected':''}>हिन्दी</option></select></div><div class="setting-row"><div><strong>Audio feedback</strong><small>Optional microphone tools for estimated feedback</small></div><input class="switch" id="audio-setting" type="checkbox" ${s.audioFeedback?'checked':''}></div><div class="setting-row"><div><strong>Reduced motion</strong><small>Minimize movement and decorative effects</small></div><input class="switch" id="motion-setting" type="checkbox" ${s.reducedMotion?'checked':''}></div></div><section class="panel"><div class="panel-title"><h3>Your data stays on this device</h3><span>Local storage only</span></div><p class="settings-note">Your practice history and preferences are saved in this browser. Microphone access is optional and audio is analyzed in real time only; it is never recorded or uploaded. Audio feedback is approximate and is not a medical assessment.</p><div style="display:flex;gap:9px;flex-wrap:wrap"><button class="outline-btn" data-action="calibrate-voice">◉ &nbsp; Calibrate voice</button><button class="outline-btn" data-action="export-data">↓ &nbsp; Export my data</button><button class="outline-btn" data-action="reset-onboarding">ⓘ &nbsp; Replay welcome</button></div></section>`;}
function bindPractice(){document.querySelectorAll('.practice-tab').forEach(b=>b.addEventListener('click',()=>{mode=b.dataset.mode;cleanup();render();}));const input=document.querySelector('#word-input');if(input){input.addEventListener('input',()=>loadWord(input.value));input.addEventListener('keydown',e=>{if(e.key==='Enter')loadWord(input.value);});document.querySelectorAll('[data-word]').forEach(b=>b.addEventListener('click',()=>{input.value=b.dataset.word;loadWord(b.dataset.word);}));loadWord(input.value);bindDiagramControls();}document.querySelectorAll('[data-exercise]').forEach(card=>card.addEventListener('click',()=>openExercise(card.dataset.exercise)));}
function loadWord(word){stopPlayback();tokens=decomposeWord(word||'');activeIndex=0;renderTokens();const canvas=document.querySelector('#anatomy-canvas');if(canvas){animator?.destroy();animator=new AnatomyAnimator(canvas);animator.reduced=state.settings.reducedMotion||matchMedia('(prefers-reduced-motion: reduce)').matches;animator.setMirror(state.settings.mirror);selectToken(0,false);}}
function renderTokens(){const strip=document.querySelector('#phoneme-strip');if(!strip)return;document.querySelector('#token-count').textContent=` · ${tokens.length} sounds`;strip.innerHTML=tokens.length?tokens.map((t,i)=>`<button class="phoneme-tile ${i===activeIndex?'active':''}" data-index="${i}" style="animation-delay:${Math.min(i*45,450)}ms"><span class="dev">${esc(t.display||t.char)}</span><small>${esc((t.ipa||'pause').slice(0,9))}</small></button>`).join(''):'<span class="helper">Type a Hindi word to see its sound sequence.</span>';strip.querySelectorAll('[data-index]').forEach(b=>b.addEventListener('click',()=>{stopPlayback();selectToken(Number(b.dataset.index),true);}));renderLesson();}
function renderLesson(){const box=document.querySelector('#lesson-card');if(!box)return;if(!tokens.length){box.innerHTML='<div class="helper">Your sound-by-sound coaching will appear here.</div>';return;}const t=tokens[activeIndex]||tokens[0];box.innerHTML=`<div class="lesson-top"><div><div class="lesson-dev">${esc(t.display||t.char||'—')}</div><div class="lesson-place">${esc(t.place||'Sound')} ${t.voiced?'· voiced':''} ${t.aspirated?'· aspirated':''}</div></div><div class="lesson-ipa">/${esc(t.ipa||'—')}/</div></div><p class="lesson-instruction">${esc(state.settings.language==='hi'?(t.instructionHi||t.instruction):t.instruction||'Notice how this sound connects to the next one.')}${t.held?' Keep the sound held through the transition.':''}</p>`;}
function targetFor(t){const poses={dental:{tip:[.48,.45],body:[.56,.55],jaw:.12},alveolar:{tip:[.50,.42],body:[.56,.54],jaw:.1},retroflex:{tip:[.54,.38],body:[.58,.5],rotation:-.52,jaw:.12},palatal:{tip:[.50,.38],body:[.52,.42],jaw:.13},velar:{tip:[.55,.57],body:[.60,.40],jaw:.14},bilabial:{tip:[.56,.59],body:[.58,.57],jaw:.08},open:{tip:[.55,.62],body:[.57,.60],jaw:.34},rounded:{tip:[.55,.61],body:[.59,.49],jaw:.13},neutral:{tip:[.55,.60],body:[.57,.56],jaw:.16}};const p=poses[t?.tongue]||poses.neutral,targets=t?.targets||{},lips=targets.lips|| (t?.tongue==='bilabial'?'closed':t?.tongue==='rounded'?'rounded':t?.tongue==='palatal'?'spread':'neutral'),nasal=!!t?.manner?.includes('nasal')||!!t?.nasal;return {...p,...targets,velum:nasal?'lowered':targets.velum||'raised',lips,voiced:!!t?.voiced,aspirated:!!t?.aspirated||t?.manner==='breath',nasal};}
function selectToken(i,animate=true){if(!tokens.length)return;activeIndex=Math.max(0,Math.min(i,tokens.length-1));document.querySelectorAll('.phoneme-tile').forEach((el,k)=>el.classList.toggle('active',k===activeIndex));renderLesson();if(animator)animator.setTarget(targetFor(tokens[activeIndex]),animate?650/Number(state.settings.animationSpeed||1):0);const tl=document.querySelector('#timeline');if(tl)tl.value=Math.round(activeIndex/Math.max(1,tokens.length-1)*100);}
function stopPlayback(){isPlaying=false;cancelAnimationFrame(playRaf);const b=document.querySelector('#play-button');if(b)b.textContent='▶';}
function playWord(){if(!tokens.length)return;if(isPlaying){stopPlayback();return;}isPlaying=true;const button=document.querySelector('#play-button');button.textContent='Ⅱ';const speed=document.querySelector('#speed-select')?.value||'slow',cycle=speed==='slow'?2000:165,loop=document.querySelector('#loop-toggle')?.checked,oneSound=loop&&document.querySelector('#loop-mode')?.value==='sound',sequenceLength=oneSound?1:tokens.length,startIndex=oneSound?activeIndex:0;let began=performance.now(),last=-1;const tick=now=>{if(!isPlaying)return;let idx=Math.floor((now-began)/cycle);if(idx>=sequenceLength){if(loop){began=now;last=-1;idx=0;}else{stopPlayback();return;}}const selected=oneSound?startIndex:idx;if(selected!==last||idx===0&&last===-1){last=selected;selectToken(selected,true);}const tl=document.querySelector('#timeline');if(tl)tl.value=oneSound?Math.round(selected/Math.max(1,tokens.length-1)*100):Math.min(100,((now-began)/(cycle*sequenceLength))*100);playRaf=requestAnimationFrame(tick);};playRaf=requestAnimationFrame(tick);}
function bindDiagramControls(){document.querySelector('#play-button')?.addEventListener('click',playWord);document.querySelector('#timeline')?.addEventListener('input',e=>{stopPlayback();selectToken(Math.round(Number(e.target.value)/100*(tokens.length-1)),true);});document.querySelector('#mirror-toggle')?.addEventListener('change',e=>{state.settings.mirror=e.target.checked;saveState(state);animator?.setMirror(e.target.checked);});document.querySelector('#mic-button')?.addEventListener('click',toggleMic);}
async function toggleMic(){if(!state.settings.audioFeedback){toast('Audio feedback is off. Turn it on in Settings to use the microphone.','warning');return;}const btn=document.querySelector('#mic-button');if(audio){audio.stop();audio=null;animator?.setNasalLeak(false);animator?.setEstimate(null);btn.textContent='◉ Try mic';document.querySelector('#audio-feedback').style.display='none';toast('Microphone stopped. No audio was saved.');return;}try{articulationWaveHistory=[];audio=new AudioEngine(updateAudio);if(!await audio.start()){audio=null;return;}document.querySelector('#audio-feedback').style.display='block';btn.textContent='■ Stop mic';toast('Mic on · audio stays on this device.','success');}catch(e){toast(e.message||'Mic permission was not granted. Continue with self-report.','warning');}}
function paintWave(container,wave,history,count,color){if(!container)return;history.push(Array.from({length:count},(_,i)=>(wave[i*3]||0)/255));if(history.length>3)history.shift();if(container.children.length!==count)container.innerHTML=Array.from({length:count},()=>'<i></i>').join('');const avg=history[0].map((_,i)=>history.reduce((sum,frame)=>sum+frame[i],0)/history.length);avg.forEach((value,i)=>{const bar=container.children[i];bar.style.height=`${Math.max(3,value*30)}px`;bar.style.background=color;});}
function updateAudio(d){const meter=document.querySelector('#audio-meter');if(!meter)return;meter.style.width=`${Math.min(100,d.rms*420)}%`;const expectedNasal=tokens[activeIndex]?.manner?.includes('nasal')||tokens[activeIndex]?.nasal;const leak=d.nasality>.63&&!expectedNasal;animator?.setNasalLeak(leak);animator?.setEstimate(d.formants);const hint=document.querySelector('#nasality-hint');if(hint)hint.style.display=leak?'block':'none';const read=document.querySelector('#pitch-readout');read.textContent=`Pitch ${d.pitch?Math.round(d.pitch)+' Hz':'—'} · nasal estimate ${Math.round(d.nasality*100)}%`;read.style.color=leak?'#d88072':'';paintWave(document.querySelector('#wave-bars'),d.wave,articulationWaveHistory,28,'#65bfac');}
