 breathing:{title:'Diaphragmatic breathing',desc:'Inhale gently for 4, pause for 4 only if comfortable, and exhale slowly for 8. Six cycles; return to ordinary breathing whenever needed.',duration:96,phase:['Breathe in','Easy optional hold','Slow exhale'],lengths:[4,4,8],cycles:6,glyph:'◌',pose:{jaw:.18,voiced:false}},
 yawn:{title:'Velum awareness · yawn–sigh',desc:'Notice the soft palate lift during an easy yawn, then keep airflow comfortable on a soft “haa”. Five repetitions.',duration:50,phase:['Easy yawn','Gentle sigh'],lengths:[5,5],cycles:5,glyph:'◡',pose:{jaw:.3,velum:'raised',voiced:false}},
 'nose-pinch':{title:'Nose-pinch contrast check',desc:'A self-observation exercise only. Do not pinch hard; stop if uncomfortable. Oral vowels should usually change little, while nasal sounds may feel blocked.',duration:0,phase:[],lengths:[],glyph:'⇄',pose:{jaw:.18,velum:'raised'}},
 vowels:{title:'Sustained oral vowels',desc:'Move through ten oral vowels for about eight seconds each. Keep the jaw and throat easy; audio feedback is only an estimate.',duration:80,phase:['अ','आ','इ','ई','उ','ऊ','ए','ऐ','ओ','औ'].map(v=>`${v} · sustain gently`),lengths:Array(10).fill(8),glyph:'आ',pose:{jaw:.24}},
