const readingWords='धीरे धीरे सुबह की रोशनी आँगन में उतर आई। पेड़ों की पत्तियाँ हवा के साथ हिलीं और दूर कहीं एक चिड़िया ने मधुर स्वर में पुकारा। उसने गहरी सहज साँस ली, फिर मुस्कुराते हुए अपनी राह पर चल पड़ा।'.split(/\s+/);
